// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint256 value, bytes calldata data) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.assume(value <= address(this).balance);
        vm.deal(address(c), 100 ether);
        uint balanceBefore = address(c).balance;
        vm.prank(actor);
        try c.sendMoney(address(0), value, data) {} catch {}
        uint balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}
